#include "lu.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// A: i x j
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// initialization function
void init_array(auto A) {
	// A: i x j
	using namespace noarr;

	const auto n = A | get_length<'i'>(); // matrix is n x n

	// ---------------------------------------------------------------------
	// 1) Initialize A
	//    - unit-lower plus some values below diagonal, 0 above
	//    - this is left as-is, already cache-friendly (row-wise traversal)
	// ---------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// ---------------------------------------------------------------------
	// 2) Make the matrix positive semi-definite:
	//    B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	//    Original code:
	//      B initialized to zero
	//      for t:
	//        for r,s:
	//          B[r][s] += A[r][t] * A[s][t];
	//
	//    This touches every B[r][s] once per t (n times), causing a lot of
	//    memory traffic on B. Instead, we compute each B[r][s] in a local
	//    accumulator and write it once:
	//
	//      for r,s:
	//        acc = 0
	//        for t:
	//          acc += A[r][t] * A[s][t]
	//        B[r][s] = acc
	//
	//    This is algebraically equivalent, but:
	//      - greatly reduces B loads/stores (one store per element),
	//      - keeps the innermost loop fully in registers.
	//
	//    Noarr usage:
	//      - outer traversal over B (dimensions 'i','j'),
	//      - inner traversal over the 1D "t_structure".
	// ---------------------------------------------------------------------
	auto B = noarr::bag(A.structure()); // A-like layout, uninitialized

	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		num_t acc = static_cast<num_t>(0);

		traverser(t_structure)
			.order(noarr::set_length<'t'>(n))
			.for_each([&](auto t_state) {
				auto t = get_index<'t'>(t_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				acc += A[rt_state] * A[st_state];
			});

		B[rs_state] = acc; // single store per element of B
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
// The attributes are preserved as in the original code.
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	const auto n = A | get_length<'i'>();

	#pragma scop
	// Outer loop over rows i
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// -----------------------------------------------------------------
		// First inner loop: 0 <= j < i
		//   This computes the L part:
		//
		//   for (j = 0; j < i; j++) {
		//     for (k = 0; k < j; k++)
		//       A[i][j] -= A[i][k] * A[k][j];
		//     A[i][j] /= A[j][j];
		//   }
		//
		// Optimization:
		//   Instead of updating A[i][j] in memory for each k, keep a local
		//   accumulator `lij` in a register:
		//
		//     lij = A[i][j];
		//     for k: lij -= ...
		//     lij /= A[j][j];
		//     A[i][j] = lij;
		//
		//   This preserves the operation order while reducing repeated
		//   loads/stores of A[i][j].
		// -----------------------------------------------------------------
		if (i_idx > 0) {
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// Load current A[i][j] into a local accumulator
				num_t lij = A[ij_state];

				// for (k = 0; k < j; k++)
				if (j_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							lij -= A[ik_state] * A[kj_state];
						});
				}

				// A[i][j] /= A[j][j];
				auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				lij /= A[jj_state];

				// Single write-back
				A[ij_state] = lij;
			});
		}

		// -----------------------------------------------------------------
		// Second inner loop: i <= j < n
		//   This computes the U part:
		//
		//   for (j = i; j < n; j++) {
		//     for (k = 0; k < i; k++)
		//       A[i][j] -= A[i][k] * A[k][j];
		//   }
		//
		// Again we use a local accumulator per A[i][j] to avoid repeatedly
		// loading/storing it inside the k-loop.
		// -----------------------------------------------------------------
		const auto len_second = n - i_idx;
		if (len_second > 0) {
			auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

			trav_j_ge_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx = get_index<'j'>(state_ij);

				auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);

				// Load current A[i][j] into local accumulator
				num_t uij = A[ij_state];

				// for (k = 0; k < i; k++)
				if (i_idx > 0) {
					traverser(k_structure)
						.order(noarr::set_length<'k'>(i_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							uij -= A[ik_state] * A[kj_state];
						});
				}

				// Single write-back
				A[ij_state] = uij;
			});
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
