constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// initialization function
//
// 1) Build A as a unit-lower matrix with some values below diagonal and 0 above.
// 2) Make A positive semi-definite by setting A = B where
//      B[r][s] = sum_t A[r][t] * A[s][t]  (i.e., B = A * A^T).
//    This step is implemented in a cache‑friendly way that:
//      - accumulates into a register and writes each B[r][s] once
//      - exploits symmetry B[r][s] == B[s][r] and computes only half
void init_array(auto A) {
	using namespace noarr;

	// A: i x j, with n = |i| = |j|
	auto n = A | get_length<'i'>();

	// ---------------------------------------------------------------------
	// Step 1: initialize A
	// ---------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const int nn = static_cast<int>(n);
		const int jj = static_cast<int>(j);

		if (j < i) {
			// A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
			num_t val = static_cast<num_t>((-jj % nn));
			val /= static_cast<num_t>(nn);
			val += static_cast<num_t>(1);
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// ---------------------------------------------------------------------
	// Step 2: make A positive semi‑definite: B = A * A^T, then A = B
	//
	// Original code:
	//   - zeroes B
	//   - for each t: for each (r,s): B[r][s] += A[r][t] * A[s][t]
	// That repeatedly loads/stores B.
	//
	// Optimized version below:
	//   - for each (r,s) with s <= r:
	//       sum = Σ_t A[r][t] * A[s][t]
	//       B[r][s] = sum
	//       if r != s: B[s][r] = sum
	//   - Each B element is written once.
	//   - We still compute exactly B = A * A^T (bit-identical), but with
	//     ~half the flops and much less memory traffic for B.
	// ---------------------------------------------------------------------
	auto B = noarr::bag(A.structure());

	// Traverser over t (the reduction index), with length fixed to n
	auto t_trav_full =
		traverser(t_structure).order(set_length<'t'>(n));

	// Iterate all (r,s); only compute for s <= r and exploit symmetry
	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		// Use only lower triangle (including diagonal) as owners
		if (s > r)
			return; // upper-triangular element is filled when (r,s) = (s,r)

		num_t sum = static_cast<num_t>(0);

		// sum_t A[r][t] * A[s][t]
		t_trav_full.for_each([&](auto t_state) {
			auto t = get_index<'t'>(t_state);

			auto rt_state = noarr::idx<'i', 'j'>(r, t);
			auto st_state = noarr::idx<'i', 'j'>(s, t);

			sum += A[rt_state] * A[st_state];
		});

		// Set B[r][s]
		B[rs_state] = sum;

		// And by symmetry, set B[s][r] when off-diagonal
		if (r != s) {
			auto sr_state = noarr::idx<'i', 'j'>(s, r);
			B[sr_state] = sum;
		}
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
//
// In-place LU factorization of A (Doolittle-like algorithm):
//   for i = 0..n-1:
//     // compute L(i,j) for j < i
//     for j = 0..i-1:
//       A[i][j] = (A[i][j] - sum_{k < j} A[i][k] * A[k][j]) / A[j][j];
//     // compute U(i,j) for j >= i
//     for j = i..n-1:
//       A[i][j] = A[i][j] - sum_{k < i} A[i][k] * A[k][j];
//
// The code below:
//   - keeps the outer structure expressed via Noarr traversers
//   - creates row and column views of A (fixing 'i' or 'j') to reduce
//     per-access indexing work and improve locality
//   - accumulates dot products in registers before updating A[i][j],
//     so each element is read/written only once per (i,j), not per k.
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	using namespace noarr;

	// A: i x j (n x n)
	auto n = A | get_length<'i'>();

	// 1D traverser over k, with maximum length n.
	// For given j or i we will restrict it using slice<'k'>(0, limit).
	auto k_trav_full =
		traverser(k_structure).order(set_length<'k'>(n));

	#pragma scop
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx   = get_index<'i'>(state_i);

		// View of the i-th row: dimension 'i' is fixed, only 'j' varies.
		auto row_i = A ^ noarr::fix<'i'>(i_idx);

		// -------------------------------------------------------------
		// First inner loop: 0 <= j < i  (compute L(i,j))
		// -------------------------------------------------------------
		if (i_idx > 0) {
			// j in [0, i_idx)
			auto trav_j_lt_i = trav_i.order(noarr::slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx    = get_index<'j'>(state_ij);

				// Column view for this j: dimension 'j' is fixed, only 'i' varies.
				auto col_j = A ^ noarr::fix<'j'>(j_idx);

				// Compute dot product: sum_{k < j} A[i][k] * A[k][j]
				num_t sum = static_cast<num_t>(0);

				if (j_idx > 0) {
					k_trav_full
						.order(noarr::slice<'k'>(0, j_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							// A[i][k] is in row_i at 'j' = k
							auto ik_state_j = noarr::idx<'j'>(k_idx);
							// A[k][j] is in col_j at 'i' = k
							auto kj_state_i = noarr::idx<'i'>(k_idx);

							sum += row_i[ik_state_j] * col_j[kj_state_i];
						});
				}

				// A[i][j] = (A[i][j] - sum) / A[j][j]
				auto ij_state_j  = noarr::idx<'j'>(j_idx); // row_i index for A[i][j]
				auto jj_state_i  = noarr::idx<'i'>(j_idx); // col_j index for A[j][j]

				num_t a_ij = row_i[ij_state_j];
				num_t a_jj = col_j[jj_state_i];

				row_i[ij_state_j] = (a_ij - sum) / a_jj;
			});
		}

		// -------------------------------------------------------------
		// Second inner loop: i <= j < n  (compute U(i,j))
		// -------------------------------------------------------------
		auto len_second = n - i_idx;
		if (len_second > 0) {
			// j in [i_idx, n)
			auto trav_j_ge_i = trav_i.order(noarr::slice<'j'>(i_idx, len_second));

			trav_j_ge_i.template for_dims<'j'>([&](auto trav_ij) {
				auto state_ij = trav_ij.state();
				auto j_idx    = get_index<'j'>(state_ij);

				// Column view for this j
				auto col_j = A ^ noarr::fix<'j'>(j_idx);

				// Compute sum_{k < i} A[i][k] * A[k][j]
				num_t sum = static_cast<num_t>(0);

				if (i_idx > 0) {
					k_trav_full
						.order(noarr::slice<'k'>(0, i_idx))
						.for_each([&](auto k_state) {
							auto k_idx = get_index<'k'>(k_state);

							auto ik_state_j = noarr::idx<'j'>(k_idx); // A[i][k] in row_i
							auto kj_state_i = noarr::idx<'i'>(k_idx); // A[k][j] in col_j

							sum += row_i[ik_state_j] * col_j[kj_state_i];
						});
				}

				// A[i][j] -= sum
				auto ij_state_j = noarr::idx<'j'>(j_idx);
				row_i[ij_state_j] -= sum;
			});
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
