#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "lu.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto t_vec = noarr::vector<'t'>();

struct tuning {
	// A: i x j
	// We keep the original layout: 'i' is the outer dimension (row),
	// 'j' is the inner dimension (column, contiguous in memory).
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// 1D helper structures for k- and t-iterations (no actual data, only for traversal)
constexpr auto k_structure = noarr::scalar<char>() ^ k_vec;
constexpr auto t_structure = noarr::scalar<char>() ^ t_vec;

// initialization function
void init_array(auto A) {
	using namespace noarr;

	const std::size_t n = A | get_length<'i'>(); // matrix is n x n
	const num_t inv_n = num_t(1) / static_cast<num_t>(n);

	// Initialize A as unit-lower plus some values below diagonal, 0 above.
	// Original formula for j < i:
	//   A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	// For 0 <= j < n: (-j % n) == -j, so this simplifies to:
	//   A[i][j] = 1 - j / n
	// We use the simplified expression but keep the same mathematical function.
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			A[state] = num_t(1) - static_cast<num_t>(j) * inv_n;
		} else if (j == i) {
			A[state] = num_t(1);
		} else { // j > i
			A[state] = num_t(0);
		}
	});

	// Make the matrix positive semi-definite:
	// B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	auto B = noarr::bag(A.structure());

	// Zero B
	traverser(B).for_each([&](auto state) {
		B[state] = num_t(0);
	});

	// Pre-build a traverser for the 't' dimension of length n
	auto t_trav = traverser(t_structure).order(set_length<'t'>(n));

	// Outer loop over t
	//
	// We view the PSD construction as a sum of rank-1 updates:
	//   For each column t, let v[r] = A[r, t].
	//   Then B += v * v^T.
	//
	// Compared to the original version, we now:
	//  * reuse A[r, t] for all s for fixed (r, t),
	//  * still traverse B in row-major order ('i' outer, 'j' inner),
	//  * keep the order of updates to B identical (t outermost, then r, then s),
	//    so the sequence of floating-point additions is unchanged.
	t_trav.for_each([&](auto t_state) {
		const std::size_t t = get_index<'t'>(t_state);

		// Iterate rows r
		traverser(B).template for_dims<'i'>([&](auto trav_r) {
			const auto state_r = trav_r.state();
			const std::size_t r = get_index<'i'>(state_r);

			// A[r, t] reused for all s for this (r, t)
			const num_t a_rt = A[noarr::idx<'i', 'j'>(r, t)];

			// Iterate columns s within row r
			trav_r.template for_dims<'j'>([&](auto trav_rs) {
				const auto state_rs = trav_rs.state();
				const std::size_t s = get_index<'j'>(state_rs);

				const num_t a_st = A[noarr::idx<'i', 'j'>(s, t)];

				// trav_rs carries both indices ('i' == r, 'j' == s)
				B[trav_rs] += a_rt * a_st;
			});
		});
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	const std::size_t n = A | get_length<'i'>();

	// Reusable 1D traverser for the 'k' loop (0 <= k < n).
	// Individual k-ranges are obtained by slicing this base traverser.
	auto k_full_trav = traverser(k_structure).order(set_length<'k'>(n));

	#pragma scop
	// Outer loop over i (row index)
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		const auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// ------------------------------------------------------------------
		// First inner loop: 0 <= j < i   (computes L(i, j))
		// ------------------------------------------------------------------
		if (i_idx > 0) {
			// Restrict j to [0, i_idx)
			auto trav_j_lt_i = trav_i.order(slice<'j'>(0, i_idx));

			trav_j_lt_i.template for_dims<'j'>([&](auto trav_ij) {
				const auto state_ij = trav_ij.state();
				const std::size_t j_idx = get_index<'j'>(state_ij);

				// Direct reference to A(i, j) to avoid re-building states
				num_t &a_ij = A[trav_ij];

				// a_ij -= sum_{k = 0}^{j-1} A(i, k) * A(k, j)
				if (j_idx > 0) {
					k_full_trav
						.order(slice<'k'>(0, j_idx))
						.for_each([&](auto k_state) {
							const std::size_t k_idx = get_index<'k'>(k_state);

							const num_t a_ik =
								A[noarr::idx<'i', 'j'>(i_idx, k_idx)];
							const num_t a_kj =
								A[noarr::idx<'i', 'j'>(k_idx, j_idx)];

							a_ij -= a_ik * a_kj;
						});
				}

				// A[i][j] /= A[j][j];
				const auto jj_state = noarr::idx<'i', 'j'>(j_idx, j_idx);
				a_ij /= A[jj_state];
			});
		}

		// ------------------------------------------------------------------
		// Second inner loop: i <= j < n   (computes U(i, j))
		// ------------------------------------------------------------------
		const std::size_t len_second = n - i_idx;
		if (len_second > 0) {
			// Restrict j to [i_idx, n)
			auto trav_j_ge_i = trav_i.order(slice<'j'>(i_idx, len_second));

			trav_j_ge_i.template for_dims<'j'>([&](auto trav_ij) {
				const auto state_ij = trav_ij.state();
				const std::size_t j_idx = get_index<'j'>(state_ij);

				num_t &a_ij = A[trav_ij];

				// a_ij -= sum_{k = 0}^{i-1} A(i, k) * A(k, j)
				if (i_idx > 0) {
					k_full_trav
						.order(slice<'k'>(0, i_idx))
						.for_each([&](auto k_state) {
							const std::size_t k_idx = get_index<'k'>(k_state);

							const num_t a_ik =
								A[noarr::idx<'i', 'j'>(i_idx, k_idx)];
							const num_t a_kj =
								A[noarr::idx<'i', 'j'>(k_idx, j_idx)];

							a_ij -= a_ik * a_kj;
						});
				}
			});
		}
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;

	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	// A: n x n
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_lu(A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (and prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

