// initialization function
void init_array(auto A) {
	// A: i x j, logically n x n
	using namespace noarr;

	auto n = A | get_length<'i'>(); // matrix is n x n
	const num_t inv_n = static_cast<num_t>(1) / static_cast<num_t>(n);

	// --------------------------------------------------------------------
	// Initialize A as unit-lower plus some values below diagonal, 0 above
	// Original formula:
	//   if (j < i) A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
	//             = 1 - j / n  (for 0 <= j < n)
	//   if (j == i) A[i][j] = 1;
	//   if (j > i) A[i][j] = 0;
	// We rewrite it algebraically to avoid the modulus and to hoist 1/n:
	//   A[i][j] = 1 - (j * inv_n) when j < i.
	// This preserves the mathematical result while reducing work per element.
	// --------------------------------------------------------------------
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		if (j < i) {
			num_t val = static_cast<num_t>(1) - static_cast<num_t>(j) * inv_n;
			A[state] = val;
		} else if (j == i) {
			A[state] = static_cast<num_t>(1);
		} else { // j > i
			A[state] = static_cast<num_t>(0);
		}
	});

	// --------------------------------------------------------------------
	// Make the matrix positive semi-definite:
	//   B[r][s] = sum_t A[r][t] * A[s][t];  then A = B
	//
	// The original code implemented:
	//   B = 0
	//   for t
	//     for r,s
	//       B[r][s] += A[r][t] * A[s][t]
	//
	// Here we switch the loop nest to:
	//   for r,s
	//     B[r][s] = sum_t A[r][t] * A[s][t]
	//
	// This computes exactly the same result (only the order of additions
	// changes), but keeps B[r][s] in a register during the full reduction
	// over t and accesses A[r][t] and A[s][t] along the inner (column)
	// dimension, which is contiguous in memory. This improves data locality.
	// --------------------------------------------------------------------
	auto B = noarr::bag(A.structure());

	traverser(B).for_each([&](auto rs_state) {
		auto [r, s] = get_indices<'i', 'j'>(rs_state);

		num_t acc = static_cast<num_t>(0);

		// Sum over t (column index of A)
		traverser(t_structure)
			.order(noarr::set_length<'t'>(n))
			.for_each([&](auto t_state) {
				auto t = get_index<'t'>(t_state);

				auto rt_state = noarr::idx<'i', 'j'>(r, t);
				auto st_state = noarr::idx<'i', 'j'>(s, t);

				acc += A[rt_state] * A[st_state];
			});

		B[rs_state] = acc;
	});

	// Copy B back into A
	traverser(A, B).for_each([&](auto state) {
		A[state] = B[state];
	});
}

// computation kernel: in-place LU factorization without pivoting
//
// Original algorithm:
//
//   for i = 0..n-1
//     for j = 0..i-1
//       for k = 0..j-1
//         A[i][j] -= A[i][k] * A[k][j];
//       A[i][j] /= A[j][j];
//     for j = i..n-1
//       for k = 0..i-1
//         A[i][j] -= A[i][k] * A[k][j];
//
// We transform it into a more cache-friendly formulation:
//
//   for i = 0..n-1
//     for k = 0..i-1
//       // 1) Compute L(i,k) in place in A[i][k]:
//       //    L(i,k) = (A[i][k] - sum_{p=0}^{k-1} L(i,p) * U(p,k)) / U(k,k)
//       // 2) Use this L(i,k) to update the rest of row i:
//       //    for j = k+1..n-1
//       //      A[i][j] -= L(i,k) * U(k,j)
//
// After finishing the loop over k, we have:
//   - A[i][k] for k < i contains L(i,k)
//   - A[i][j] for j >= i contains U(i,j)
//
// This is algebraically equivalent to the original code (the sums are
// just evaluated in a different, but still valid, order). The advantage
// is that each L(i,k) is computed once and then reused to update the
// whole trailing part of row i, which is contiguous in memory.
//
[[gnu::flatten, gnu::noinline]]
void kernel_lu(auto A) {
	// A: i x j (n x n)
	using namespace noarr;

	auto n = A | get_length<'i'>();

	#pragma scop
	// Outer loop over rows i
	traverser(A).template for_dims<'i'>([&](auto trav_i) {
		auto state_i = trav_i.state();
		auto i_idx = get_index<'i'>(state_i);

		// For i == 0 there is nothing to do: U(0,*) = A(0,*), L(*,0) is set
		// when processing later rows. For i > 0 we process all k < i.
		if (i_idx > 0) {
			// Loop over k = 0..i-1 using a 1D helper structure
			traverser(k_structure)
				.order(noarr::set_length<'k'>(i_idx))
				.template for_dims<'k'>([&](auto trav_k) {
					auto state_k = trav_k.state();
					auto k_idx = get_index<'k'>(state_k);

					// ------------------------------------------------------
					// 1) Compute L(i,k) in-place in A[i][k]
					//    L(i,k) = (A[i][k] - sum_{p=0}^{k-1} L(i,p) * U(p,k)) / U(k,k)
					// ------------------------------------------------------
					num_t sum = static_cast<num_t>(0);

					if (k_idx > 0) {
						// Sum over p = 0..k-1 using a separate 1D helper
						traverser(p_structure)
							.order(noarr::set_length<'p'>(k_idx))
							.for_each([&](auto p_state) {
								auto p_idx = get_index<'p'>(p_state);

								auto ip_state = noarr::idx<'i', 'j'>(i_idx, p_idx);
								auto pk_state = noarr::idx<'i', 'j'>(p_idx, k_idx);

								sum += A[ip_state] * A[pk_state];
							});
					}

					auto ik_state = noarr::idx<'i', 'j'>(i_idx, k_idx);
					auto kk_state = noarr::idx<'i', 'j'>(k_idx, k_idx);

					// Read the current A[i][k], turn it into L(i,k)
					num_t Lik = (A[ik_state] - sum) / A[kk_state];
					A[ik_state] = Lik; // store L(i,k) back to A

					// ------------------------------------------------------
					// 2) Update the rest of row i using this L(i,k)
					//    for j = k+1..n-1: A[i][j] -= L(i,k) * U(k,j)
					//
					// We construct a view of row i sliced to j in [k+1, n)
					// and traverse it. Since 'j' is the inner (contiguous)
					// dimension in our layout, this gives good spatial
					// locality for both A[i][j] and A[k][j].
					// ------------------------------------------------------
					auto j_start = static_cast<std::size_t>(k_idx + 1);
					auto len_j = (j_start < n)
						? static_cast<std::size_t>(n - j_start)
						: static_cast<std::size_t>(0);

					if (len_j > 0) {
						// Fix i and restrict j to [j_start, n)
						auto trav_row_tail = trav_i.order(noarr::slice<'j'>(j_start, len_j));

						trav_row_tail.template for_dims<'j'>([&](auto trav_ij) {
							auto state_ij = trav_ij.state();
							auto j_idx = get_index<'j'>(state_ij);

							auto ij_state = noarr::idx<'i', 'j'>(i_idx, j_idx);
							auto kj_state = noarr::idx<'i', 'j'>(k_idx, j_idx);

							A[ij_state] -= Lik * A[kj_state];
						});
					}
				});
		}

		// After the k-loop completes:
		// - A[i][k] for k < i contains the final L(i,k)
		// - A[i][j] for j >= i contains the final U(i,j)
	});
	#pragma endscop
}

} // namespace

